"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition, type Variants } from "motion/react";
import { Children, type ReactNode } from "react";

import { cn } from "@/lib/utils";

/** How one page hands over to the next. */
export type PageTransitionEffect = "curtain" | "pixels" | "stagger" | "sweep" | "blur" | "glow";

/** Props for a page transition. Change `pageKey` to move to a new page. */
export interface PageTransitionProps {
  /** Identifies the page on show, such as the route. A new key plays the transition. */
  pageKey: string;
  effect?: PageTransitionEffect;
  children: ReactNode;
  className?: string;
}

// Covers close in on the old page and open off the new one. ease-in-out suits
// a there-and-back, and 0.32 seconds each way keeps a navigation under 0.7 seconds.
const COVER: Transition = { duration: 0.32, ease: [0.65, 0, 0.35, 1] };
const FADE_OUT: Transition = { duration: 0.15, ease: [0.55, 0.085, 0.68, 0.53] };
const RISE: Transition = { duration: 0.35, ease: [0.23, 1, 0.32, 1] };
const PIXEL_COLUMNS = 8;
const PIXEL_ROWS = 5;
// The last diagonal of cells starts this long after the first, so the swipe reads as a wave.
const PIXEL_SPREAD = 0.24;

const CURTAIN: Variants = {
  initial: { y: "0%" },
  animate: { y: "-100%", transition: COVER },
  exit: { y: ["100%", "0%"], transition: COVER },
};

const SWEEP: Variants = {
  initial: { x: "0%" },
  animate: { x: "100%", transition: COVER },
  exit: { x: ["-100%", "0%"], transition: COVER },
};

const BLUR: Variants = {
  initial: { opacity: 0, filter: "blur(0.5rem)" },
  animate: { opacity: 1, filter: "blur(0rem)", transition: RISE },
  exit: { opacity: 0, filter: "blur(0.5rem)", transition: { duration: 0.2, ease: [0.55, 0.085, 0.68, 0.53] } },
};

const STAGGER_PAGE: Variants = {
  initial: {},
  animate: { transition: { staggerChildren: 0.06 } },
  exit: { opacity: 0, transition: FADE_OUT },
};

const STAGGER_CHILD: Variants = {
  initial: { opacity: 0, y: "0.75rem" },
  animate: { opacity: 1, y: "0rem", transition: RISE },
};

// The band of light rises once, from below the frame to above it. The old page is clipped
// away at the band's centre and the new page is uncovered there, so both pages show at
// once and neither needs a background.
const GLOW_SECONDS = 0.7;
const GLOW: Transition = { duration: GLOW_SECONDS, ease: [0.65, 0, 0.35, 1] };

// A leaving page first shows its whole height, then clears from the bottom up. A page that
// leaves before it has fully arrived would otherwise keep its top clipped, and once the page
// before it has gone, the top of the frame would show no page at all. An arriving page's lower
// edge is already at the bottom, so only its top edge moves.
const GLOW_PAGE: Variants = {
  initial: { clipPath: "inset(120% 0% -20% 0%)" },
  animate: { clipPath: "inset(-20% 0% -20% 0%)", transition: GLOW },
  exit: { clipPath: ["inset(-20% 0% -20% 0%)", "inset(-20% 0% 120% 0%)"], transition: GLOW },
};

// The band sits in the middle of a layer as tall as the frame, so moving the layer from
// 70% to -70% keeps the band's centre on the clip edge above. It animates `transform`, not `y`,
// so the browser runs it on the same clock as the clip and the two stay together.
const GLOW_BAND: Variants = {
  initial: { transform: "translateY(70%)", opacity: 1 },
  animate: {
    transform: "translateY(-70%)",
    // The trail is still inside the frame when the crest has left, so the band fades over the last quarter.
    opacity: [1, 1, 0],
    transition: { ...GLOW, opacity: { duration: GLOW_SECONDS, times: [0, 0.75, 1], ease: "linear" } },
  },
  // A band still on its way when the next page arrives fades out; a finished one is already gone.
  exit: { opacity: 0, transition: { duration: 0.15 } },
};

/** The motion the page itself makes. The cover effects move a cover instead, so the page holds still. */
function pageVariants(effect: PageTransitionEffect): Variants | undefined {
  if (effect === "blur") return BLUR;
  if (effect === "stagger") return STAGGER_PAGE;
  if (effect === "glow") return GLOW_PAGE;
  return undefined;
}

const pixelDelay = (index: number, total: number) => {
  const column = index % PIXEL_COLUMNS;
  const row = Math.floor(index / PIXEL_COLUMNS);
  return ((column + row) / total) * PIXEL_SPREAD;
};

const PIXEL: Variants = {
  initial: { opacity: 1 },
  animate: (delay: number) => ({ opacity: 0, transition: { duration: 0.12, delay } }),
  exit: (delay: number) => ({ opacity: 1, transition: { duration: 0.12, delay } }),
};

/** The surface that hides the swap. It uses the border colour: visible on the page in both themes, and never a bright flash in dark mode. */
function Cover({ effect }: { effect: "curtain" | "pixels" | "sweep" }) {
  if (effect === "pixels") {
    const cells = PIXEL_COLUMNS * PIXEL_ROWS;
    const diagonals = PIXEL_COLUMNS + PIXEL_ROWS - 2;
    return (
      <div
        aria-hidden="true"
        // grid-cols-8 and grid-rows-5 match PIXEL_COLUMNS and PIXEL_ROWS.
        className="pointer-events-none absolute inset-0 z-10 grid grid-cols-8 grid-rows-5"
      >
        {Array.from({ length: cells }, (_, index) => (
          // Cells overlap by a hair so no seam shows between them.
          <motion.span key={index} variants={PIXEL} custom={pixelDelay(index, diagonals)} className="-m-0.5 bg-border" />
        ))}
      </div>
    );
  }
  return (
    <motion.div
      aria-hidden="true"
      variants={effect === "curtain" ? CURTAIN : SWEEP}
      className="pointer-events-none absolute inset-0 z-10 bg-border"
    />
  );
}

/**
 * The band of light that rides the edge between the old page and the new one. Its crest
 * runs from one chart colour to the next across the frame, and a fainter trail in two
 * more follows it, so the band takes the design system's own colours.
 */
function GlowBand() {
  return (
    <motion.div
      aria-hidden="true"
      initial="initial"
      animate="animate"
      exit="exit"
      variants={GLOW_BAND}
      className="pointer-events-none absolute inset-0 z-10"
    >
      {/* The trail starts at the crest and fades out below it. */}
      <div className="absolute inset-x-0 top-1/2 h-3/5 bg-linear-to-b from-chart-4/60 via-chart-5/30 to-transparent blur-xl" />
      {/* The crest is as tall as the frame. It is strongest at its middle line and fades out above and below it. */}
      <div className="absolute inset-x-0 top-1/2 h-full -translate-y-1/2 blur-md">
        <div className="absolute inset-0 bg-linear-to-b from-transparent via-chart-1 to-transparent mask-r-from-0%" />
        <div className="absolute inset-0 bg-linear-to-b from-transparent via-chart-2 to-transparent mask-l-from-0%" />
      </div>
    </motion.div>
  );
}

/**
 * Plays a transition when the page changes. Curtain, pixels and sweep cover the
 * old page and uncover the new one. Stagger brings the new page's blocks in one
 * after another, and blur dissolves one page into the next. Glow raises a band of
 * light through the frame and leaves the new page below it. With reduced motion
 * the new page shows at once.
 */
export function PageTransition({ pageKey, effect = "curtain", children, className }: PageTransitionProps) {
  const reduceMotion = useReducedMotion();

  if (reduceMotion) {
    return (
      <div key={pageKey} className={cn("relative", className)}>
        {children}
      </div>
    );
  }

  const covered = effect === "curtain" || effect === "pixels" || effect === "sweep";
  // Glow shows both pages at once, stacked in one grid cell. Every other effect waits for the old page to leave.
  const glow = effect === "glow";

  return (
    // The cover's clipping stays inside this frame, so it never spills over the rest of the app.
    <div className={cn("relative overflow-hidden", glow && "grid", className)}>
      <AnimatePresence mode={glow ? "sync" : "wait"} initial={false}>
        {/* Pages and bands take separate prefixes, so a page key can never match a band key. */}
        <motion.div
          key={`page:${pageKey}`}
          initial="initial"
          animate="animate"
          exit="exit"
          variants={pageVariants(effect)}
          className={cn("relative h-full", glow && "col-start-1 row-start-1")}
        >
          {effect === "stagger"
            ? Children.map(children, (child) => <motion.div variants={STAGGER_CHILD}>{child}</motion.div>)
            : children}
          {covered ? <Cover effect={effect} /> : null}
        </motion.div>
        {glow ? <GlowBand key={`band:${pageKey}`} /> : null}
      </AnimatePresence>
    </div>
  );
}
